def count_vowels(text: str) -> int:
    vowels: set[str] = {'a', 'e', 'i', 'o', 'u'}
    count: int = 0
    for char in text:
        if char.lower() in vowels:
            count += 1
    return count

def process_texts(texts: list[str]) -> dict[str, int]:
    results: dict[str, int] = {}
    for t in texts:
        results[t] = count_vowels(t)
    return results

def get_top_vowel_counts(data: dict[str, int], top_n: int) -> list[tuple[str, int]]:
    sorted_items: list[tuple[str, int]] = sorted(data.items(), key=lambda item: item[1], reverse=True)
    return sorted_items[:top_n]

