        ("a@b.c", True),
        ("@example.com", False),
        ("test@", False),
        ("test.com", False),
        ("test@.com", False),
        ("test@example.", False),
        ("test@example.c", True),
        ("a@b.c.d", True)
    ]

    results: dict[str, bool] = {}
    for email_str, expected in test_cases:
        actual: bool = validate_email(email_str)
        results[email_str] = actual == expected
    return results

if __name__ == '__main__':
