import math

def circle_area(radius: float) -> float:
    """
    Calculates the area of a circle given its radius.

    Args:
        radius: The radius of the circle.

    Returns:
        The area of the circle.
    """
    if radius < 0:
        raise ValueError("Radius cannot be negative.")
    return math.pi * (radius ** 2)

def main() -> None:
    test_radii: list[float] = [1.0, 0.0, 2.5]
    expected_areas: list[float] = [math.pi * 1.0**2, 0.0, math.pi * 2.5**2]

    for i in range(len(test_radii)):
        r: float = test_radii[i]
        expected_a: float = expected_areas[i]
        calculated_a: float = circle_area(r)
        print(f"Radius: {r}, Expected Area: {expected_a}, Calculated Area: {calculated_a}")
        assert abs(calculated_a - expected_a) < 1e-9, f"Test failed for radius {r}"

    # Example of using a dictionary for more complex scenarios
    area_map: dict[float, float] = {0.5: math.pi * 0.5**2, 3.0: math.pi * 3.0**2}
    for r_val, expected_val in area_map.items():
        calculated_val: float = circle_area(r_val)
        print(f"Radius from map: {r_val}, Calculated Area: {calculated_val}")

    try:
        circle_area(-1.0)
    except ValueError as e:
        print(f"Caught expected error: {e}")

if __name__ == "__main__":
    main()

