"""Simulate a FIFO queue and report on scripted queue sessions."""

Operation = tuple[str, object]
Script = list[str]
Tally = dict[str, int]
Bounds = tuple[int, int]


def simulate_queue(
    operations: list[Operation],
) -> list[int]:
    """Apply enqueue/dequeue operations and return the final queue contents."""
    queue: list[int] = []
    for name, item in operations:
        if name == "enqueue":
            if not isinstance(item, int):
                raise ValueError("enqueue requires an integer item")
            queue.append(item)
        elif name == "dequeue":
            if queue:
                queue.pop(0)
        else:
            raise ValueError(f"unknown operation: {name}")
    return queue


def count_operations(operations: list[Operation]) -> Tally:
    """Count how often each operation name appears."""
    tally: Tally = {}
    for name, _item in operations:
        tally[name] = tally.get(name, 0) + 1
    return tally


def parse_script(lines: Script) -> list[Operation]:
    """Turn textual commands like 'enqueue 7' or 'dequeue' into operations."""
    operations: list[Operation] = []
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if len(parts) > 1:
            operations.append((parts[0], int(parts[1])))
        else:
            operations.append((parts[0], None))
    return operations


def queue_extremes(queue: list[int]) -> Bounds:
    """Return the front and back values of a non-empty queue."""
    if not queue:
        raise ValueError("queue is empty")
    return queue[0], queue[-1]


def format_report(operations: list[Operation]) -> str:
    """Describe a session: operation counts, final queue and its ends."""
    final = simulate_queue(operations)
    tally = count_operations(operations)
    pieces = [f"{name}={tally[name]}" for name in sorted(tally)]
    summary = f"{', '.join(pieces)} -> {final}"
    if final:
        front, back = queue_extremes(final)
        summary += f" (front={front}, back={back})"
    return summary


def main() -> None:
    scripts: dict[str, Script] = {
        "basic": ["enqueue 1", "enqueue 2", "dequeue"],
        "drain": ["dequeue"],
        "mixed": ["enqueue 5", "dequeue", "enqueue 8", "enqueue 13", "dequeue"],
    }
    for label, lines in scripts.items():
        print(f"{label}: {format_report(parse_script(lines))}")


if __name__ == "__main__":
    main()

