def most_frequent_char(text: str) -> str:
    char_counts: dict[str, int] = {}
    char_order: list[str] = []

    for char in text.lower():
        if char == ' ':
            continue
        if char not in char_counts:
            char_counts[char] = 0
            char_order.append(char)
        char_counts[char] += 1

    if not char_counts:
        return ''

    max_count: int = -1
    most_frequent: str = ''

    for char_in_order in char_order:
        current_count: int = char_counts[char_in_order]
        if current_count > max_count:
            max_count = current_count
            most_frequent = char_in_order

    return most_frequent

