Row = list[int]
Table = list[Row]


def multiplication_table(n: int) -> Table:
    """Print an n x n multiplication table and return it as a list of rows."""
    if n < 0:
        raise ValueError("table size must be non-negative")
    table: Table = []
    for row in range(1, n + 1):
        products: list[int] = [row * col for col in range(1, n + 1)]
        table.append(products)
    for line in render(table):
        print(line)
    return table


def column_widths(table: Table) -> list[int]:
    """Width in characters needed by each column of the table."""
    widths = [0] * (len(table[0]) if table else 0)
    for row in table:
        for index, value in enumerate(row):
            widths[index] = max(widths[index], len(str(value)))
    return widths


def render(table: Table) -> list[str]:
    """Turn the table into right-aligned text lines."""
    widths = column_widths(table)
    lines: list[str] = []
    for row in table:
        cells = [str(value).rjust(widths[index]) for index, value in enumerate(row)]
        lines.append(" ".join(cells))
    return lines


def shape(table: Table) -> tuple[int, int]:
    """Number of rows and columns of the table."""
    if not table:
        return (0, 0)
    return (len(table), len(table[0]))


def diagonal(table: Table) -> list[int]:
    """The perfect squares sitting on the main diagonal."""
    return [row[index] for index, row in enumerate(table)]


def value_counts(table: Table) -> dict[int, int]:
    """How many times each product occurs in the table."""
    counts: dict[int, int] = {}
    for row in table:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    return counts


def summary(table: Table) -> dict[str, int]:
    """A few aggregate facts about the table."""
    rows, cols = shape(table)
    counts = value_counts(table)
    repeated = sum(1 for occurrences in counts.values() if occurrences > 1)
    return {
        "rows": rows,
        "columns": cols,
        "cells": rows * cols,
        "distinct": len(counts),
        "repeated": repeated,
        "largest": max(counts) if counts else 0,
    }


def main() -> None:
    for size in (2, 5):
        print(f"--- {size} x {size} ---")
        table = multiplication_table(size)
        facts = summary(table)
        squares = diagonal(table)
        print("squares:", ", ".join(str(value) for value in squares))
        for name, value in facts.items():
            print(f"{name}: {value}")
        print()


if __name__ == "__main__":
    main()

