def run_length_encode(s: str) -> str:
    if not s:
        return ""

    encoded_parts: list[str] = []
    current_char: str = s[0]
    current_count: int = 1

    for i in range(1, len(s)):
        char: str = s[i]
        if char == current_char:
            current_count += 1
        else:
            encoded_parts.append(current_char + str(current_count))
            current_char = char
            current_count = 1

    encoded_parts.append(current_char + str(current_count))
    return "".join(encoded_parts)

