def is_anagram(s1: str, s2: str) -> bool:
    def normalize_string(s: str) -> str:
        return s.replace(" ", "").lower()

    normalized_s1: str = normalize_string(s1)
    normalized_s2: str = normalize_string(s2)

    if len(normalized_s1) != len(normalized_s2):
        return False

    char_count: dict[str, int] = {}
    for char in normalized_s1:
        char_count[char] = char_count.get(char, 0) + 1

    for char in normalized_s2:
        if char not in char_count or char_count[char] == 0:
            return False
        char_count[char] -= 1

    # Check if all counts are zero (all characters matched)
    remaining_counts: list[int] = list(char_count.values())
    return all(count == 0 for count in remaining_counts)

