    """Return the character length of every line, newline excluded."""
    lengths: List[int] = []
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            lengths.append(len(line.rstrip("\n")))
    return lengths


def count_words(filepath: str) -> Dict[str, int]:
    """Return how often each whitespace-separated token occurs."""
    frequencies: Dict[str, int] = {}
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            for token in line.split():
                word = token.strip(".,;:!?\"'()[]").lower()
                if word:
                    frequencies[word] = frequencies.get(word, 0) + 1
    return frequencies


def line_extremes(lengths: List[int]):
    """Return the shortest and longest line length, (0, 0) when empty."""
    if not lengths:
        return (0, 0)
    return (min(lengths), max(lengths))


def top_words(frequencies: Dict[str, int], limit: int):
    """Return the most frequent words, ties broken alphabetically."""
    ranked = sorted(frequencies, key=lambda word: (-frequencies[word], word))
    return ranked[:limit]


def summarize(filepath: str, frequencies: Dict[str, int]):
    """Collect the line/word statistics of a single file."""
    extremes: Tuple[int, int] = line_extremes(read_line_lengths(filepath))
    shortest, longest = extremes
    return {
        "lines": count_file_lines(filepath),
        "words": sum(frequencies.values()),
        "unique_words": len(frequencies),
        "shortest_line": shortest,
        "longest_line": longest,
    }


def format_report(filepath: str) -> List[str]:
    """Render a human readable report for one file."""
    frequencies = count_words(filepath)
    stats = summarize(filepath, frequencies)
    rows = [f"{os.path.basename(filepath)}: {stats['lines']} line(s)"]
    for key in ("words", "unique_words", "shortest_line", "longest_line"):
        rows.append(f"  {key.replace('_', ' ')}: {stats[key]}")
    for word in top_words(frequencies, 3):
        rows.append(f"  {word} -> {frequencies[word]}")
    return rows


def main(argv: List[str]) -> int:
    paths = argv[1:]
    if not paths:
        print("usage: linecount FILE [FILE ...]", file=sys.stderr)
        return 2
    total = 0
    for path in paths:
        for row in format_report(path):
            print(row)
        total += count_file_lines(path)
    if len(paths) > 1:
        print(f"total: {total} line(s)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

