def is_valid_url(url: str) -> bool:
    schemes: tuple[str, ...] = ('http://', 'https://')

    is_scheme_valid: bool = False
    for scheme in schemes:
        if url.startswith(scheme):
            is_scheme_valid = True
            break

    if not is_scheme_valid:
        return False

    scheme_end_index: int = url.find('://') + 3
    domain_part: str = url[scheme_end_index:]

    if '.' not in domain_part:
        return False

    parts: list[str] = domain_part.split('.')
    if len(parts) < 2:
        return False

    for part in parts:
        if not part:
            return False

    return True

