Rectangle = tuple[float, float]
RectangleList = list[Rectangle]


def rectangle_area(width: float, height: float) -> float:
    """Return the area of a rectangle with the given width and height."""
    if width < 0 or height < 0:
        raise ValueError("width and height must be non-negative")
    return float(width) * float(height)


def parse_dimensions(text: str) -> RectangleList:
    """Parse lines of the form "width x height" into dimension pairs."""
    rectangles: RectangleList = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        parts = stripped.replace("*", "x").split("x")
        if len(parts) != 2:
            raise ValueError(f"cannot parse dimensions from {stripped!r}")
        rectangles.append((float(parts[0]), float(parts[1])))
    return rectangles


def areas(rectangles: RectangleList) -> list[float]:
    """Compute the area of every rectangle in the list."""
    return [rectangle_area(width, height) for width, height in rectangles]


def total_area(rectangles: RectangleList) -> float:
    """Sum the areas of all rectangles."""
    return sum(areas(rectangles))


def classify(rectangles: RectangleList) -> dict[str, int]:
    """Count how many rectangles are squares and how many are oblong."""
    counts: dict[str, int] = {"square": 0, "oblong": 0}
    for width, height in rectangles:
        key = "square" if width == height else "oblong"
        counts[key] += 1
    return counts


def largest(rectangles: RectangleList) -> Rectangle:
    """Return the rectangle with the greatest area."""
    if not rectangles:
        raise ValueError("no rectangles given")
    return max(rectangles, key=lambda pair: rectangle_area(*pair))


def integer_side_lengths(rectangles: RectangleList) -> list[int]:
    """Collect, in sorted order, the side lengths that are whole numbers."""
    sides: list[int] = []
    for width, height in rectangles:
        for side in (width, height):
            if side == int(side):
                sides.append(int(side))
    return sorted(set(sides))


def report(rectangles: RectangleList) -> str:
    """Build a human-readable summary of the parsed rectangles."""
    lines: list[str] = [
        f"{width:g} x {height:g} = {area:.2f}"
        for (width, height), area in zip(rectangles, areas(rectangles))
    ]
    counts = classify(rectangles)
    best = largest(rectangles)
    lines.append(f"total area: {total_area(rectangles):.2f}")
    lines.append(f"squares: {counts['square']}, oblong: {counts['oblong']}")
    lines.append(f"largest: {best[0]:g} x {best[1]:g}")
    lines.append(f"whole side lengths: {integer_side_lengths(rectangles)}")
    return "\n".join(lines)


def main() -> None:
    data = """
    5 x 10
    2.5 x 4
    3 x 3
    7.5 * 1.2
    """
    print(report(parse_dimensions(data)))


if __name__ == "__main__":
    main()

