def weighted_average(values: list[float], weights: list[float]) -> float:
    if not values or not weights:
        raise ValueError("Input lists cannot be empty.")
    if len(values) != len(weights):
        raise ValueError("Values and weights lists must have the same length.")

    weighted_sum: float = 0.0
    total_weight: float = 0.0

    for i in range(len(values)):
        value: float = values[i]
        weight: float = weights[i]
        weighted_sum += value * weight
        total_weight += weight

    if total_weight == 0:
        raise ValueError("Total weight cannot be zero.")

    avg: float = weighted_sum / total_weight
    return avg

def main() -> None:
    test_cases: list[tuple[list[float], list[float], float]] = [
        ([10.0, 20.0, 30.0], [1.0, 2.0, 1.0], 20.0),
        ([5.0, 10.0], [0.5, 0.5], 7.5),
        ([1.0], [10.0], 1.0),
        ([100.0, 0.0], [0.25, 0.75], 25.0)
    ]

    for values, weights, expected in test_cases:
        result: float = weighted_average(values, weights)
        print(f"weighted_average({values}, {weights}) -> {result}, Expected: {expected}, Match: {result == expected}")

if __name__ == "__main__":
    main()

