def int_to_roman(num: int) -> str:
    """
    Converts an integer (1-3999) to its Roman numeral representation.
    """
    roman_map: list[tuple[int, str]] = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    result: list[str] = []
    current_num: int = num

    for value, numeral_char in roman_map:
        while current_num >= value:
            result.append(numeral_char)
            current_num -= value

    return "".join(result)

def find_duplicate(numbers: list[int]) -> int:
    seen: dict[int, int] = {}
    for num in numbers:
        if num in seen:
            return num
        seen[num] = 1
    return -1 # Should not be reached based on problem description.

def find_duplicate_math(numbers: list[int]) -> int:
    n: int = len(numbers) - 1
    expected_sum: int = n * (n + 1) // 2
    actual_sum: int = sum(numbers)
    return actual_sum - expected_sum

