"""Helpers for merging small string-to-integer dictionaries."""

Stage = dict[str, int]
Change = tuple[int, int]


def merge_dicts(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> dict[str, int]:
    """Merge two dictionaries; values from dict2 win on conflicting keys."""
    merged: dict[str, int] = {}
    merged.update(dict1)
    merged.update(dict2)
    return merged


def conflicting_keys(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> list[str]:
    """Keys present in both inputs, in the order they appear in dict1."""
    shared: list[str] = []
    for key in dict1:
        if key in dict2:
            shared.append(key)
    return shared


def overwrite_pairs(
    dict1: Stage,
    dict2: Stage,
) -> list[Change]:
    """For every conflicting key, the (old, new) value pair after merging."""
    pairs: list[Change] = []
    for key in conflicting_keys(dict1, dict2):
        pairs.append((dict1[key], dict2[key]))
    return pairs


def merge_all(stages: list[Stage]) -> Stage:
    """Fold merge_dicts over a list of dictionaries, left to right."""
    result: Stage = {}
    for current in stages:
        result = merge_dicts(result, current)
    return result


def size_report(
    dict1: Stage,
    dict2: Stage,
) -> tuple[int, int]:
    """Keys taken from dict1 only, and the number taken from dict2."""
    shared = conflicting_keys(dict1, dict2)
    return len(dict1) - len(shared), len(dict2)


def format_merge(dict1: Stage, dict2: Stage) -> str:
    merged = merge_dicts(dict1, dict2)
    items: list[str] = [f"{key}={value}" for key, value in merged.items()]
    kept, taken = size_report(dict1, dict2)
    body = "{" + ", ".join(items) + "}"
    return f"{body}  (kept {kept} from first, took {taken} from second)"


def main() -> None:
    first: dict[str, int] = {'a': 1, 'b': 2}
    second: dict[str, int] = {'b': 3, 'c': 4}
    print(merge_dicts(first, second))
    print(merge_dicts({'x': 10}, {'y': 20}))

    print("conflicts:", conflicting_keys(first, second))
    for old, new in overwrite_pairs(first, second):
        print(f"  {old} -> {new}")
    print(format_merge(first, second))

    stages: list[Stage] = [
        {'cpu': 2, 'ram': 8},
        {'ram': 16, 'disk': 512},
        {'disk': 1024, 'gpu': 1},
    ]
    combined = merge_all(stages)
    print("combined:", combined)
    print(f"keys={len(combined)} sum={sum(combined.values())}")


if __name__ == "__main__":
    main()

