Span = tuple[int, int]
Schedule = dict[str, Span]
Conflict = tuple[str, str]


def has_overlap(task1_start: int, task1_end: int, task2_start: int, task2_end: int) -> bool:
    """Return True when the two half-open hour ranges share at least one hour."""
    validate_interval(task1_start, task1_end)
    validate_interval(task2_start, task2_end)
    return task1_start < task2_end and task2_start < task1_end


def validate_interval(start: int, end: int) -> None:
    if not (0 <= start <= 24 and 0 <= end <= 24):
        raise ValueError(f"hours must lie in 0..24, got ({start}, {end})")
    if start >= end:
        raise ValueError(f"start must precede end, got ({start}, {end})")


def parse_schedule(lines: list[str]) -> Schedule:
    """Turn lines like 'standup 9-10' into a name -> (start, end) mapping."""
    schedule: Schedule = {}
    for line in lines:
        name, span = line.split()
        start_text, end_text = span.split("-")
        bounds: Span = (int(start_text), int(end_text))
        validate_interval(*bounds)
        schedule[name] = bounds
    return schedule


def find_conflicts(schedule: Schedule) -> list[Conflict]:
    """List every pair of task names whose hour ranges collide."""
    names = sorted(schedule, key=lambda name: schedule[name])
    conflicts: list[Conflict] = []
    for index, first in enumerate(names):
        for second in names[index + 1:]:
            first_start, first_end = schedule[first]
            second_start, second_end = schedule[second]
            if has_overlap(first_start, first_end, second_start, second_end):
                conflicts.append((first, second))
    return conflicts


def hourly_load(schedule: Schedule) -> dict[int, int]:
    """Count how many tasks cover each hour slot."""
    load: dict[int, int] = {}
    for start, end in schedule.values():
        for hour in range(start, end):
            load[hour] = load.get(hour, 0) + 1
    return load


def busy_hours(schedule: Schedule) -> list[int]:
    """Every hour slot covered by at least one task, in ascending order."""
    return sorted(hourly_load(schedule))


def format_report(schedule: Schedule) -> list[str]:
    report: list[str] = []
    for name, (start, end) in sorted(schedule.items(), key=lambda item: item[1]):
        report.append(f"{name}: {start:02d}:00-{end:02d}:00")
    for first, second in find_conflicts(schedule):
        report.append(f"conflict: {first} <-> {second}")
    load = hourly_load(schedule)
    if load:
        busiest = max(load, key=lambda hour: (load[hour], -hour))
        report.append(f"peak hour {busiest:02d}:00 with {load[busiest]} task(s)")
    return report


def main() -> None:
    print(has_overlap(9, 12, 11, 14))
    print(has_overlap(9, 10, 10, 12))
    raw: list[str] = ["standup 9-10", "review 9-12", "lunch 12-13", "deploy 11-14"]
    schedule = parse_schedule(raw)
    for line in format_report(schedule):
        print(line)
    print("busy:", busy_hours(schedule))


if __name__ == "__main__":
    main()

