def is_valid_luhn(card_number: str) -> bool:
    digits: list[int] = [int(d) for d in card_number]
    total_sum: int = 0
    is_even_position: bool = False

    for i in range(len(digits) - 1, -1, -1):
        digit: int = digits[i]
        if is_even_position:
            doubled_digit: int = digit * 2
            if doubled_digit > 9:
                total_sum += (doubled_digit % 10) + (doubled_digit // 10)
            else:
                total_sum += doubled_digit
        else:
            total_sum += digit
        is_even_position = not is_even_position

    return total_sum % 10 == 0

