def is_palindromic_number(number: int) -> bool:
    if number < 0:
        return False

    s: str = str(number)
    left: int = 0
    right: int = len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1

    return True

