def encrypt_shift(text: str, shift: int) -> str:
    result_chars: list[str] = []
    for char_code in map(ord, text):
        if 'a' <= chr(char_code) <= 'z':
            start: int = ord('a')
            shifted_code: int = (char_code - start + shift) % 26 + start
            result_chars.append(chr(shifted_code))
        elif 'A' <= chr(char_code) <= 'Z':
            start: int = ord('A')
            shifted_code: int = (char_code - start + shift) % 26 + start
            result_chars.append(chr(shifted_code))
        else:
            result_chars.append(chr(char_code))
    return "".join(result_chars)

