Row = list[int]
Matrix = list[Row]
Pair = tuple[Matrix, Matrix]


def matrix_shape(matrix: Matrix) -> tuple[int, int]:
    """Return the (rows, columns) shape of a rectangular matrix."""
    rows = len(matrix)
    columns = len(matrix[0]) if rows else 0
    for row in matrix:
        if len(row) != columns:
            raise ValueError("matrix rows have inconsistent lengths")
    return rows, columns


def validate_2x2(matrix: Matrix, name: str) -> None:
    """Raise ValueError unless the given matrix is exactly 2x2."""
    shape: tuple[int, int] = matrix_shape(matrix)
    if shape != (2, 2):
        raise ValueError(f"{name} must be 2x2, got {shape[0]}x{shape[1]}")


def multiply_2x2_matrices(matrix_a: Matrix, matrix_b: Matrix) -> Matrix:
    """Multiply two 2x2 matrices and return the 2x2 product."""
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    product: Matrix = []
    for i in range(2):
        row: list[int] = []
        for j in range(2):
            row.append(matrix_a[i][0] * matrix_b[0][j] + matrix_a[i][1] * matrix_b[1][j])
        product.append(row)
    return product


def matrix_power_2x2(matrix: Matrix, exponent: int) -> Matrix:
    """Raise a 2x2 matrix to a non-negative integer power."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    validate_2x2(matrix, "matrix")
    result: Matrix = [[1, 0], [0, 1]]
    base = [row[:] for row in matrix]
    while exponent:
        if exponent & 1:
            result = multiply_2x2_matrices(result, base)
        base = multiply_2x2_matrices(base, base)
        exponent >>= 1
    return result


def summarize_2x2(matrix: Matrix) -> dict[str, int]:
    """Describe a 2x2 matrix by its trace, determinant and entry total."""
    validate_2x2(matrix, "matrix")
    flat: list[int] = [value for row in matrix for value in row]
    return {
        "trace": matrix[0][0] + matrix[1][1],
        "determinant": matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0],
        "total": sum(flat),
    }


def format_matrix(matrix: Matrix) -> str:
    """Render a matrix as a compact single-line string."""
