def roman_to_int(roman_numeral: str) -> int:
    roman_map: dict[str, int] = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_value: int = 0
    n: int = len(roman_numeral)

    for i in range(n):
        current_value: int = roman_map[roman_numeral[i]]
        if i + 1 < n and roman_map[roman_numeral[i+1]] > current_value:
            integer_value -= current_value
        else:
            integer_value += current_value

    return integer_value

