        ('LVIII', 58),
        ('MCMXCIV', 1994)
    ]
    for numeral, expected in test_cases:
        result: int = roman_to_int(numeral)
        print(f"'{numeral}' -> {result} (Expected: {expected})")
        assert result == expected

if __name__ == "__main__":
