def generate_primes(n: int) -> list[int]:
    if n < 2:
        return []

    primes: list[int] = []
    candidates: list[int] = list(range(2, n + 1))

    for num in candidates:
        is_prime: bool = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return primes

