def convert_base(number: int, base: int) -> str:
    if not (2 <= base <= 16):
        raise ValueError("Base must be between 2 and 16")
    if number == 0:
        return "0"

    digits: list[str] = "0123456789ABCDEF"
    result_stack: list[str] = []

    current_number: int = number
    while current_number > 0:
        remainder: int = current_number % base
        result_stack.append(digits[remainder])
        current_number //= base

    return "".join(reversed(result_stack))

