def find_all_occurrences(text: str, pattern: str) -> list[int]:
    """
    Finds all starting indices where the pattern is found in the text.
    """
    occurrences: list[int] = []
    text_length: int = len(text)
    pattern_length: int = len(pattern)

    if pattern_length == 0:
        return list(range(text_length + 1))

    if text_length < pattern_length:
        return occurrences

    for i in range(text_length - pattern_length + 1):
        current_slice: str = text[i : i + pattern_length]
        if current_slice == pattern:
            occurrences.append(i)

    return occurrences

def main() -> None:
    test_cases: list[tuple[str, str, list[int]]] = [
        ('ababab', 'aba', [0, 2]),
        ('hello world', 'o', [4, 7]),
        ('aaaaa', 'aa', [0, 1, 2, 3]),
        ('abcde', 'xyz', []),
        ('single', 'single', [0]),
        ('empty pattern', '', list(range(14))),
        ('', 'pattern', []),
        ('testtest', 'test', [0, 4]),
    ]

    for text, pattern, expected in test_cases:
        result: list[int] = find_all_occurrences(text, pattern)
        assert result == expected, f"Text: '{text}', Pattern: '{pattern}', Expected: {expected}, Got: {result}"
        print(f"Test passed for '{text}' and '{pattern}'. Result: {result}")

if __name__ == "__main__":
    main()

import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def find_primes_in_range(start: int, end: int) -> list[int]:
    primes: list[int] = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

def get_prime_factors(num: int) -> dict[int, int]:
    factors: dict[int, int] = {}
    d: int = 2
    temp_num: int = num
    while d * d <= temp_num:
        while temp_num % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_num //= d
        d += 1
    if temp_num > 1:
        factors[temp_num] = factors.get(temp_num, 0) + 1
    return factors

def main() -> None:
    test_numbers: list[int] = [1, 2, 7, 10, 13, 100]
    for num_to_check in test_numbers:
        print(f"Is {num_to_check} prime? {is_prime(num_to_check)}")

    primes_in_1_to_20: list[int] = find_primes_in_range(1, 20)
    print(f"Primes between 1 and 20: {primes_in_1_to_20}")

    factor_this: int = 42
    factors_of_42: dict[int, int] = get_prime_factors(factor_this)
    print(f"Prime factors of {factor_this}: {factors_of_42}")

if __name__ == "__main__":
