import re

def reverse_words_with_punctuation(sentence: str) -> str:
    words: list[str] = re.findall(r"\w+[.,!?;]?|\S", sentence)
    reversed_words: list[str] = words[::-1]
    result_parts: list[str] = []

    for i, word in enumerate(reversed_words):
        if i > 0 and not (word.startswith((',', '.', '!', '?', ';')) or result_parts[-1].endswith((',', '.', '!', '?', ';'))):
            result_parts.append(' ')
        result_parts.append(word)

    return "".join(result_parts).strip()

