def find_divisors(n: int) -> list[int]:
    divs: list[int] = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

