            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

def test_find_divisors() -> None:
    test_cases: List[Tuple[int, List[int]]] = [
        (12, [1, 2, 3, 4, 6, 12]),
        (7, [1, 7]),
        (1, [1]),
        (36, [1, 2, 3, 4, 6, 9, 12, 18, 36]),
        (100, [1, 2, 4, 5, 10, 20, 25, 50, 100]),
        (2, [1, 2]),
        (0, [])
    ]

    for number, expected_divisors in test_cases:
        if number == 0:
            try:
                find_divisors(number)
                assert False, f"find_divisors({number}) should have raised an error"
            except ValueError:
                pass
            continue
        actual_divisors: List[int] = find_divisors(number)
        assert actual_divisors == expected_divisors, \
            f"For n={number}, expected {expected_divisors}, but got {actual_divisors}"
    print("All test cases passed!")

