import re

def simple_calculator(expression: str) -> int:
    """
    Parses a simple arithmetic expression involving addition and subtraction
    of positive integers and returns the integer result.
    """
    parts: list[str] = re.split(r'([+\-])', expression)

    if not parts or len(parts) < 3:
        raise ValueError("Invalid expression format")

    numbers: list[int] = [int(p) for p in parts[::2]]
    operators: list[str] = parts[1::2]

    if not numbers:
        raise ValueError("No numbers found in expression")

    result: int = numbers[0]
    for i, op in enumerate(operators):
        if op == '+':
            result += numbers[i + 1]
        elif op == '-':
            result -= numbers[i + 1]
        else:
            raise ValueError(f"Unsupported operator: {op}")

    return result

test_cases: dict[str, int] = {
    '5+3': 8,
    '10-2': 8,
    '15+5-2': 18,
    '7': 7,
    '100-50+10': 60
}

for expr, expected in test_cases.items():
    actual: int = simple_calculator(expr)
    assert actual == expected, f"Expression: '{expr}', Expected: {expected}, Got: {actual}"
    print(f"'{expr}' = {actual} (Correct)")

def binary_search(sorted_list: list[int], target: int) -> int:
    low: int = 0
    high: int = len(sorted_list) - 1
    found_index: int = -1

    while low <= high:
        mid: int = (low + high) // 2
        mid_value: int = sorted_list[mid]

        if mid_value == target:
            found_index = mid
            break
        elif mid_value < target:
            low = mid + 1
        else:
            high = mid - 1
    return found_index

