def power_recursive(base: int, exponent: int) -> int:
    """
    Calculates base raised to the power of exponent using recursion.
    Assumes exponent is non-negative.
    """
    if exponent == 0:
        return 1
    elif exponent == 1:
        return base
    else:
        half_power: int = power_recursive(base, exponent // 2)
        if exponent % 2 == 0:
            return half_power * half_power
        else:
            return base * half_power * half_power

