def is_valid_isbn10(isbn: str) -> bool:
    if len(isbn) != 10:
        return False

    digits: list[int] = []
    for i, char in enumerate(isbn):
        if i < 9:
            if not char.isdigit():
                return False
            digits.append(int(char))
        else:
            if char.isdigit():
                digits.append(int(char))
            elif char == 'X':
                digits.append(10)
            else:
                return False

    if len(digits) != 10:
        return False

    checksum: int = 0
    for i, digit in enumerate(digits[:-1]):
        checksum += (digit * (i + 1))
    checksum += (digits[9] * 10)

    return checksum % 11 == 0

