def record_expense(expenses: List[Dict[str, Union[str, float]]], description: str, amount: float, date_str: str) -> None:
    new_expense: Dict[str, Union[str, float]] = {
        'description': description,
        'amount': amount,
        'date': date_str
    }
    expenses.append(new_expense)

def get_total_expenses(expenses: List[Dict[str, Union[str, float]]]) -> float:
    total: float = 0.0
    for expense_item in expenses:
        total += float(expense_item['amount'])
    return total

def get_expenses_by_description(expenses: List[Dict[str, Union[str, float]]], search_term: str) -> List[Dict[str, Union[str, float]]]:
    filtered_expenses: List[Dict[str, Union[str, float]]] = []
    for expense_item in expenses:
        if search_term.lower() in str(expense_item['description']).lower():
            filtered_expenses.append(expense_item)
    return filtered_expenses

def main() -> None:
    my_expenses: List[Dict[str, Union[str, float]]] = []
    record_expense(my_expenses, 'Groceries', 50.0, '2023-10-25')
    record_expense(my_expenses, 'Dinner', 25.50, '2023-10-26')
    record_expense(my_expenses, 'Utilities', 75.20, '2023-10-27')

    print(f"All expenses: {my_expenses}")
    print(f"Total expenses: {get_total_expenses(my_expenses):.2f}")

    dinner_expenses: List[Dict[str, Union[str, float]]] = get_expenses_by_description(my_expenses, 'dinner')
    print(f"Dinner expenses: {dinner_expenses}")

if __name__ == "__main__":
    main()

