import sys


def is_valid_us_zip_code(code: str) -> bool:
    """Return True when code is a string of exactly five decimal digits."""
    if not isinstance(code, str):
        return False
    if len(code) != 5:
        return False
    return all(character in "0123456789" for character in code)


def digits_of(code: str) -> list[int]:
    """Split a validated zip code into its five individual digits."""
    if not is_valid_us_zip_code(code):
        raise ValueError(f"not a valid US zip code: {code!r}")
    return [int(character) for character in code]


def valid_codes(
    codes: list[str],
) -> list[str]:
    """Keep only the candidates that are well formed zip codes."""
    return [code for code in codes if is_valid_us_zip_code(code)]


def invalid_codes(
    codes: list[str],
) -> list[str]:
    """Keep only the candidates that are rejected by validation."""
    return [code for code in codes if not is_valid_us_zip_code(code)]


def tally(
    codes: list[str],
) -> tuple[int, int]:
    """Count how many codes of a batch are valid and how many are not."""
    return len(valid_codes(codes)), len(invalid_codes(codes))


def prefix_counts(
    codes: list[str],
) -> dict[str, int]:
    """Count valid codes per three-digit sectional centre prefix."""
    counts: dict[str, int] = {}
    for code in valid_codes(codes):
        prefix = code[:3]
        counts[prefix] = counts.get(prefix, 0) + 1
    return counts


def parse_batch(text: str) -> list[str]:
    """Read whitespace or comma separated candidate codes from raw text."""
    return text.replace(",", " ").split()


def report(text: str) -> str:
    """Build a human readable validation report for a raw batch of codes."""
    codes = parse_batch(text)
    good, bad = tally(codes)
    lines: list[str] = [f"{good} valid, {bad} invalid"]
    for code in valid_codes(codes):
        digits = digits_of(code)
        lines.append(f"  {code} -> digits {digits} sum {sum(digits)}")
    for code in invalid_codes(codes):
        lines.append(f"  {code} -> rejected")
    counts = prefix_counts(codes)
    for prefix in sorted(counts):
        lines.append(f"  prefix {prefix}: {counts[prefix]}")
    return "\n".join(lines)


def main() -> None:
    arguments: list[str] = sys.argv[1:]
    text = " ".join(arguments) if arguments else "90210, 90211 1234 902100 abcde"
    print(report(text))


if __name__ == "__main__":
    main()

