import datetime

def calculate_age(birthdate: datetime.date) -> int:
    current_date: datetime.date = datetime.date(2023, 10, 26)

    age: int = current_date.year - birthdate.year

    if (current_date.month, current_date.day) < (birthdate.month, birthdate.day):
        age -= 1

    return age

def get_example_dates() -> list[datetime.date]:
    return [
        datetime.date(1990, 1, 1),
        datetime.date(2000, 11, 15),
        datetime.date(2023, 10, 26),
        datetime.date(1985, 5, 10),
        datetime.date(2005, 3, 20)
    ]

def run_examples() -> dict[str, int]:
    results: dict[str, int] = {}
    example_dates: list[datetime.date] = get_example_dates()

    for birth_date_obj in example_dates:
        age_calculated: int = calculate_age(birth_date_obj)
        results[str(birth_date_obj)] = age_calculated

    return results

if __name__ == "__main__":
    example_results: dict[str, int] = run_examples()
    for date_str, age_val in example_results.items():
        print(f"Birthdate: {date_str}, Age: {age_val}")

