def caesar_encrypt(text: str, shift: int) -> str:
    encrypted_chars: list[str] = []
    for char in text:
        if 'a' <= char <= 'z':
            start = ord('a')
            encrypted_chars.append(chr(start + (ord(char) - start + shift) % 26))
        elif 'A' <= char <= 'Z':
            start = ord('A')
            encrypted_chars.append(chr(start + (ord(char) - start + shift) % 26))
        else:
            encrypted_chars.append(char)
    return "".join(encrypted_chars)

