SEPARATORS = " -"
GROUP_SIZES: list[int] = [3, 3, 4]


def digit_values(text: str) -> list[int]:
    """Return the decimal value of every digit character in `text`, in order."""
    values: list[int] = []
    for ch in text:
        if ch.isdigit():
            values.append(int(ch))
    return values


def separator_slots() -> tuple[int, int]:
    """Digit counts after which a hyphen or space may appear."""
    first = GROUP_SIZES[0]
    second = first + GROUP_SIZES[1]
    return first, second


def is_valid_us_phone_number(text: str) -> bool:
    digits = digit_values(text)
    if len(digits) != sum(GROUP_SIZES):
        return False
    slots: tuple[int, int] = separator_slots()
    used: list[int] = []
    seen_digits = 0
    for ch in text:
        if ch.isdigit():
            seen_digits += 1
        elif ch in SEPARATORS:
            if seen_digits not in slots or seen_digits in used:
                return False
            used.append(seen_digits)
        else:
            return False
    return True


def format_number(text: str) -> str:
    digits = digit_values(text)
    groups: list[str] = []
    start = 0
    for size in GROUP_SIZES:
        groups.append("".join(str(value) for value in digits[start:start + size]))
        start += size
    return "-".join(groups)


def classify(numbers: list[str]):
    tally: dict[str, int] = {"valid": 0, "invalid": 0}
    for number in numbers:
        if is_valid_us_phone_number(number):
            tally["valid"] += 1
        else:
            tally["invalid"] += 1
    return tally


def main() -> None:
    samples: list[str] = [
        "123-456-7890",
        "123 456 7890",
        "1234567890",
        "(123) 456-7890",
        "12-3456-7890",
    ]
    for number in samples:
        valid = is_valid_us_phone_number(number)
        print(f"{number!r}: {valid}")
        if valid:
            print(f"    normalized={format_number(number)}")
    report = classify(samples)
    print(f"valid={report['valid']} invalid={report['invalid']}")


if __name__ == "__main__":
    main()

