def generate_initials(full_name: str) -> str:
    if not full_name:
        return ""

    words: list[str] = full_name.split()
    initials_list: list[str] = []

    for word in words:
        if word:
            initials_list.append(word[0].upper())

    return ".".join(initials_list)

def main() -> None:
    test_cases: dict[str, str] = {
        'John Doe': 'J.D.',
        '   Alice   Wonderland  ': 'A.W.',
        '  Bob   ': 'B.',
        '': '',
        'single': 'S.',
        'first middle last': 'F.M.L.',
        '  leading space': 'L.S.',
        'trailing space  ': 'T.S.',
        '  multiple   spaces   between   words  ': 'M.S.B.W.'
    }

    results: list[tuple[str, str]] = []
    for name, expected in test_cases.items():
        initials: str = generate_initials(name)
        results.append((initials, expected))
        assert initials == expected, f"For '{name}', expected '{expected}', got '{initials}'"

    print("All test cases passed!")
    for result_initials, result_expected in results:
        print(f"Result: {result_initials}, Expected: {result_expected}")

if __name__ == '__main__':
    main()

