import string

def is_pangram(text: str) -> bool:
    """Checks if a given string is a pangram."""
    alphabet: set[str] = set(string.ascii_lowercase)
    seen_letters: set[str] = set()

    for char in text:
        lower_char: str = char.lower()
        if lower_char in alphabet:
            seen_letters.add(lower_char)
            if len(seen_letters) == len(alphabet):
                return True
    return False

