def binary_to_gray(binary_string: str) -> str:
    """Converts a binary string to its equivalent Gray code string."""
    if not binary_string:
        return ""

    gray_bits: list[str] = [binary_string[0]]
    for i in range(1, len(binary_string)):
        current_bit: int = int(binary_string[i])
        previous_bit: int = int(binary_string[i - 1])
        gray_bits.append(str(current_bit ^ previous_bit))

