import math


def calculate_future_value_simple(principal: float, rate: float, years: int) -> float:
    """Future value of a lump sum under simple interest compounded annually."""
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if rate < 0:
        raise ValueError("rate must be non-negative")
    if years < 0:
        raise ValueError("years must be non-negative")
    return float(principal * (1.0 + rate * years))


def parse_year_range(spec: str) -> tuple[int, int]:
    """Turn a textual span such as '1-5' or '3' into an inclusive (first, last) pair."""
    parts = spec.split("-")
    if len(parts) == 1:
        single = int(parts[0])
        return single, single
    if len(parts) != 2:
        raise ValueError(f"cannot parse year range {spec!r}")
    first, last = int(parts[0]), int(parts[1])
    if first > last:
        raise ValueError(f"year range {spec!r} is reversed")
    return first, last


def expand_years(span: tuple[int, int]):
    """List every year in an inclusive span."""
    first, last = span
    years: list[int] = list(range(first, last + 1))
    return years


def value_table(
    principal: float,
    rate: float,
    years: list[int],
) -> dict[int, float]:
    """Map each requested year to the future value reached at that point."""
    return {year: calculate_future_value_simple(principal, rate, year) for year in years}


def years_to_targets(
    principal: float,
    rate: float,
    targets: list[float],
) -> dict[str, int]:
    """For each target amount, the first whole year at which it is met or exceeded."""
    if rate == 0:
        raise ValueError("a zero rate never reaches a higher target")
    needed = {}
    for target in targets:
        if target <= principal:
            needed[f"{target:.2f}"] = 0
        else:
            growth = (target / principal) - 1.0
            needed[f"{target:.2f}"] = math.ceil(growth / rate)
    return needed


def format_report(table: dict[int, float]):
    lines: list[str] = []
    for year in sorted(table):
        lines.append(f"year {year:>2}: {table[year]:10.2f}")
    return lines


def main() -> None:
    principal, rate = 1000.0, 0.05
    span = parse_year_range("1-5")
    schedule = value_table(principal, rate, expand_years(span))
    print(f"Simple interest on {principal:.2f} at {rate:.2%}")
    for line in format_report(schedule):
        print(line)

    targets = [1200.0, 1500.0, 2000.0]
    waits = years_to_targets(principal, rate, targets)
    for amount, year_count in waits.items():
        print(f"reaching {amount} takes {year_count} year(s)")


if __name__ == "__main__":
    main()

