def base_n_to_base_10(num_str: str, base: int) -> int:
    """Converts a number from base N string to its base-10 integer equivalent."""
    if not (2 <= base <= 36):
        raise ValueError("Base must be between 2 and 36.")

    conversion_map: dict[str, int] = {str(i): i for i in range(10)}
    for i in range(26):
        conversion_map[chr(ord('A') + i)] = 10 + i

    result: int = 0
    power: int = 0
    for digit_char in reversed(num_str):
        digit_value: int = conversion_map[digit_char.upper()]
        if digit_value >= base:
            raise ValueError(f"Digit '{digit_char}' is out of range for base {base}.")

        result += digit_value * (base ** power)
        power += 1

    return result

