def rotate_matrix_90_clockwise(matrix: list[list[int]]) -> list[list[int]]:
    """
    Rotates a square matrix by 90 degrees clockwise in-place.
    """
    n: int = len(matrix)
    if n == 0:
        return matrix

    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for row_index in range(n):
        matrix[row_index].reverse()

    return matrix

