from __future__ import annotations

import os


def read_first_n_lines(filepath: str, n: int) -> list[str]:
    """Return at most the first `n` lines of `filepath`, newlines included."""
    if n <= 0:
        return []
    lines: list[str] = []
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            lines.append(line)
            if len(lines) == n:
                break
    return lines


def line_lengths(
    lines: list[str],
) -> list[int]:
    """Length of every line with trailing newline characters stripped."""
    return [len(line.rstrip("\n")) for line in lines]


def span(
    lengths: list[int],
) -> tuple[int, int]:
    """Shortest and longest line length; (0, 0) when there is nothing to measure."""
    if not lengths:
        return (0, 0)
    return (min(lengths), max(lengths))


def word_counts(
    lines: list[str],
) -> dict[str, int]:
    """Case-insensitive frequency of the words found in `lines`."""
    counts: dict[str, int] = {}
    for line in lines:
        for word in line.split():
            key = word.strip(".,;:!?").lower()
            if key:
                counts[key] = counts.get(key, 0) + 1
    return counts


def write_text_file(filepath: str, body: str) -> None:
    with open(filepath, "w", encoding="utf-8") as handle:
        handle.write(body)


def format_report(filepath: str, n: int) -> list[str]:
    """Human readable summary of the first `n` lines of `filepath`."""
    head = read_first_n_lines(filepath, n)
    lengths = line_lengths(head)
    shortest, longest = span(lengths)
    report: list[str] = [f"{filepath}: {len(head)} line(s) read (requested {n})"]
    report.append(f"  lengths={lengths} shortest={shortest} longest={longest}")
    frequencies = word_counts(head)
    for word in sorted(frequencies, key=lambda w: (-frequencies[w], w))[:3]:
        report.append(f"  {word}: {frequencies[word]}")
    return report


def main() -> None:
    path = "data.txt"
    write_text_file(path, "Line 1\nLine 2\nLine 3\n")
    try:
        print(read_first_n_lines(path, 2))
        print(read_first_n_lines(path, 5))
        for requested in (0, 1, 3, 10):
            for row in format_report(path, requested):
                print(row)
    finally:
        os.remove(path)


if __name__ == "__main__":
    main()

