def merge_dicts(d1: dict[str, int], d2: dict[str, int]) -> dict[str, int]:
    """
    Merges two dictionaries. If a key exists in both, the value from the second dictionary takes precedence.

    Args:
        d1: The first dictionary.
        d2: The second dictionary.

    Returns:
        A new dictionary with merged key-value pairs.
    """
    merged: dict[str, int] = d1.copy()
    for key, value in d2.items():
        merged[key] = value
