def get_divisors(n: int) -> list[int]:
    divs: list[int] = [1]
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    return divs

