from typing import Any

Leaves = list[Any]


def flatten_list(
    nested_list: list[Any],
) -> list[Any]:
    """Return a single, non-nested list containing every leaf of nested_list."""
    flat: list[Any] = []
    for item in nested_list:
        if isinstance(item, list):
            flat.extend(flatten_list(item))
        else:
            flat.append(item)
    return flat


def max_depth(nested_list: list[Any]) -> int:
    """Depth of the deepest nesting level (a flat list has depth 1)."""
    deepest = 1
    for item in nested_list:
        if isinstance(item, list):
            deepest = max(deepest, 1 + max_depth(item))
    return deepest


def leaves_by_depth(
    nested_list: list[Any],
    level: int = 1,
) -> dict[int, Leaves]:
    """Group the leaves of nested_list by the nesting level they live at."""
    grouped: dict[int, Leaves] = {}
    for item in nested_list:
        if isinstance(item, list):
            for depth, values in leaves_by_depth(item, level + 1).items():
                grouped.setdefault(depth, []).extend(values)
        else:
            grouped.setdefault(level, []).append(item)
    return grouped


def type_counts(
    flat: list[Any],
) -> dict[str, int]:
    """Count how many leaves of each type name a flattened list holds."""
    counts: dict[str, int] = {}
    for value in flat:
        name = type(value).__name__
        counts[name] = counts.get(name, 0) + 1
    return counts


def shape(
    nested_list: list[Any],
) -> tuple[int, int]:
    """Return (number of leaves, deepest nesting level)."""
    return len(flatten_list(nested_list)), max_depth(nested_list)


def describe(nested_list: Leaves) -> str:
    """Build a one-line report about a nested list and its flattened form."""
    flat = flatten_list(nested_list)
    size, depth = shape(nested_list)
    kinds = type_counts(flat)
    kind_text = ", ".join(f"{name}={count}" for name, count in sorted(kinds.items()))
    levels = leaves_by_depth(nested_list)
    level_text = " | ".join(
        f"level {depth_key}: {values}" for depth_key, values in sorted(levels.items())
    )
    return (
        f"{nested_list}\n  -> {flat}\n"
        f"  leaves={size} depth={depth} types({kind_text})\n"
        f"  {level_text}"
    )


def main() -> None:
    samples: list[Leaves] = [
        [1, [2, 3], 4, [5, [6]]],
        [1, 2, 3],
        [[["a"], "b"], [], [1.5, [True, [None]]]],
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)

    totals: dict[str, int] = {}
    for sample in samples:
        for name, count in type_counts(flatten_list(sample)).items():
            totals[name] = totals.get(name, 0) + count
    print("combined type counts:", dict(sorted(totals.items())))


if __name__ == "__main__":
    main()

