def int_to_roman(num: int) -> str:
    if not 1 <= num <= 3999:
        raise ValueError("Input must be between 1 and 3999")

    roman_map: list[tuple[int, str]] = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result_parts: list[str] = []
    current_num: int = num

    for value, symbol in roman_map:
        while current_num >= value:
            result_parts.append(symbol)
            current_num -= value

    final_roman_numeral: str = "".join(result_parts)
    return final_roman_numeral

def nth_prime(n: int) -> int:
    if n == 1:
        return 2
    primes: list[int] = [2]
    candidate: int = 3
    while len(primes) < n:
        is_prime: bool = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 2
    return primes[-1]

