        self.val: int = val
        self.next: 'ListNode | None' = next

def remove_nth_from_end(head: ListNode | None, n: int) -> ListNode | None:
    if head is None:
        return None

    dummy: ListNode = ListNode(0, head)
    slow: ListNode = dummy
    fast: ListNode | None = dummy.next

    for _ in range(n):
        if fast:
            fast = fast.next
        else:
            return head # n is greater than list length, should not happen per problem context

    while fast:
        slow = slow.next  # type: ignore[assignment]
        fast = fast.next

    if slow.next:
        slow.next = slow.next.next

    return dummy.next

