def find_peak_element(nums: list[int]) -> int:
    left: int = 0
    right: int = len(nums) - 1

    while left < right:
        mid: int = (left + right) // 2
        current_val: int = nums[mid]

        if mid + 1 < len(nums) and current_val < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid

    return left

