def digits_of(n: int) -> list[int]:
    """Return the decimal digits of a non-negative integer, most significant first."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return [0]
    digits: list[int] = []
    while n > 0:
        n, remainder = divmod(n, 10)
        digits.append(remainder)
    digits.reverse()
    return digits


def sum_digits(n: int) -> int:
    """Sum the decimal digits of a non-negative integer."""
    return sum(digits_of(n))


def digit_frequency(n: int) -> dict[int, int]:
    """Count how often each digit occurs in n."""
    counts: dict[int, int] = {}
    for digit in digits_of(n):
        counts[digit] = counts.get(digit, 0) + 1
    return counts


def digit_extremes(n: int) -> tuple[int, int]:
    """Return the smallest and largest digit of n."""
    digits = digits_of(n)
    return min(digits), max(digits)


def digital_root(n: int) -> int:
    """Repeatedly sum digits until a single digit remains."""
    total = n
    while total > 9:
        total = sum_digits(total)
    return total


def sum_digits_many(
    numbers: list[int],
) -> dict[int, int]:
    """Map each input number to its digit sum."""
    return {number: sum_digits(number) for number in numbers}


def parse_numbers(text: str) -> list[int]:
    """Parse a whitespace- or comma-separated list of non-negative integers."""
    tokens = text.replace(",", " ").split()
    numbers: list[int] = []
    for token in tokens:
        if not token.isdigit():
            raise ValueError(f"not a non-negative integer: {token!r}")
        numbers.append(int(token))
    return numbers


def format_report(
    numbers: list[int],
) -> list[str]:
    """Build one human-readable summary line per number."""
    sums = sum_digits_many(numbers)
    lines = []
    for number in numbers:
        low, high = digit_extremes(number)
        repeated = sorted(
            digit for digit, count in digit_frequency(number).items() if count > 1
        )
        lines.append(
            f"{number}: sum={sums[number]} root={digital_root(number)} "
            f"min={low} max={high} repeated={repeated}"
        )
    return lines


def main() -> None:
    numbers = parse_numbers("12345, 7 900 987654321")
    for line in format_report(numbers):
        print(line)


if __name__ == "__main__":
    main()

