def filter_by_length(
    strings: list[str],
    min_length: int,
) -> list[str]:
    """Return the strings strictly longer than min_length."""
    if min_length < 0:
        raise ValueError("min_length must be non-negative")
    return [text for text in strings if len(text) > min_length]


def lengths_of(
    strings: list[str],
) -> list[int]:
    """Return the length of every string, in the original order."""
    return [len(text) for text in strings]


def length_bounds(
    strings: list[str],
) -> tuple[int, int]:
    """Return the shortest and longest length found in strings."""
    sizes = lengths_of(strings)
    if not sizes:
        return (0, 0)
    return (min(sizes), max(sizes))


def count_by_length(
    strings: list[str],
) -> dict[int, int]:
    """Map each observed length to the number of strings having it."""
    tally: dict[int, int] = {}
    for size in lengths_of(strings):
        tally[size] = tally.get(size, 0) + 1
    return tally


def summarize(
    strings: list[str],
    min_length: int,
) -> dict[str, int]:
    """Build a small report about filtering strings at min_length."""
    kept = filter_by_length(strings, min_length)
    shortest, longest = length_bounds(strings)
    return {
