import math

def circle_area(radius: float) -> float:
    """
    Calculates the area of a circle given its radius.

    Args:
        radius: The radius of the circle.

    Returns:
        The area of the circle.
    """
    if radius < 0:
        raise ValueError("Radius cannot be negative")
    return math.pi * (radius ** 2)

def main() -> None:
    test_radii: list[float] = [1.0, 0.0, 2.5]
    expected_areas: list[float] = [math.pi * 1**2, math.pi * 0**2, math.pi * 2.5**2]

    for i in range(len(test_radii)):
        r: float = test_radii[i]
        actual_area: float = circle_area(r)
        expected_area: float = expected_areas[i]
        print(f"Radius: {r}, Expected Area: {expected_area:.5f}, Actual Area: {actual_area:.5f}")

    try:
        circle_area(-1.0)
    except ValueError as e:
        print(f"Caught expected error for negative radius: {e}")

if __name__ == "__main__":
    main()

def power_recursive(base: float, exponent: int) -> float:
    if exponent == 0:
        return 1.0
    elif exponent == 1:
        return base
    else:
        half_power: float = power_recursive(base, exponent // 2)
        if exponent % 2 == 0:
            return half_power * half_power
        else:
            return base * half_power * half_power

def main() -> None:
    test_cases: list[tuple[float, int, float]] = [
        (2.0, 3, 8.0),
        (5.0, 0, 1.0),
        (10.0, 2, 100.0),
        (3.0, 1, 3.0),
        (2.5, 2, 6.25),
        (0.0, 5, 0.0),
        (1.0, 100, 1.0)
    ]

    results: dict[str, float] = {}
    for base_val, exp_val, expected_val in test_cases:
        calculated_val: float = power_recursive(base_val, exp_val)
        results[f"{base_val}^{exp_val}"] = calculated_val
        print(f"power_recursive({base_val}, {exp_val}) = {calculated_val} (Expected: {expected_val})")

    # Example of accessing results
    print(f"\nResult for 2.0^3: {results['2.0^3']}")

if __name__ == "__main__":
    main()

