    100: "Continue",
    101: "Switching Protocols",
    200: "OK",
    201: "Created",
    202: "Accepted",
    204: "No Content",
    301: "Moved Permanently",
    302: "Found",
    304: "Not Modified",
    400: "Bad Request",
    401: "Unauthorized",
    403: "Forbidden",
    404: "Not Found",
    405: "Method Not Allowed",
    409: "Conflict",
    418: "I'm a teapot",
    429: "Too Many Requests",
    500: "Internal Server Error",
    501: "Not Implemented",
    502: "Bad Gateway",
    503: "Service Unavailable",
    504: "Gateway Timeout",
}

CLASS_NAMES: dict[str, str] = {
    "1xx": "Informational",
    "2xx": "Success",
    "3xx": "Redirection",
    "4xx": "Client Error",
    "5xx": "Server Error",
}


def get_http_status_desc(status_code: int) -> str:
    return STATUS_TEXT.get(status_code, "Unknown Status")


def class_bounds(status_code: int) -> tuple[int, int]:
    low = (status_code // 100) * 100
    return low, low + 99


def class_label(status_code: int) -> str:
    low, high = class_bounds(status_code)
    key = f"{low // 100}xx"
    if key not in CLASS_NAMES:
        return "Unrecognized"
    return f"{CLASS_NAMES[key]} ({low}-{high})"


def parse_codes(text: str) -> list[int]:
    codes: list[int] = []
    for token in text.replace(",", " ").split():
        if token.isdigit():
            codes.append(int(token))
    return codes


def count_by_class(
    codes: list[int],
) -> dict[str, int]:
    tally: dict[str, int] = {}
    for code in codes:
        label = class_label(code)
        tally[label] = tally.get(label, 0) + 1
    return tally


def format_report(
    codes: list[int],
) -> list[str]:
    lines = [f"{code}: {get_http_status_desc(code)}" for code in codes]
    for label, count in sorted(count_by_class(codes).items()):
        lines.append(f"  {label}: {count}")
    return lines


def main() -> None:
    raw = "200 301, 404 418 500 999 503 204"
    for line in format_report(parse_codes(raw)):
        print(line)


if __name__ == "__main__":
