def is_valid_isbn10(isbn: str) -> bool:
    """
    Validates an ISBN-10 string.
    """
    if len(isbn) != 10:
        return False

    total: int = 0
    multipliers: list[int] = list(range(10, 0, -1))

    for i, char in enumerate(isbn):
        current_digit: int
        if char.isdigit():
            current_digit = int(char)
        elif char == 'X' and i == 9:
            current_digit = 10
        else:
            return False
        total += current_digit * multipliers[i]

    is_valid: bool = (total % 11 == 0)
    return is_valid

