def normalize(s: str) -> str:
    """Lowercase the text and drop everything that is not a letter or digit."""
    return "".join(ch.lower() for ch in s if ch.isalnum())


def char_counts(text: str) -> dict[str, int]:
    """Count how often each character of an already normalized text occurs."""
    counts: dict[str, int] = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def parity_summary(
    counts: dict[str, int],
) -> tuple[int, int]:
    """Return how many characters occur an odd and an even number of times."""
    odd = 0
    even = 0
    for freq in counts.values():
        if freq % 2:
            odd += 1
        else:
            even += 1
    return odd, even


def is_palindromic_permutation(s: str) -> bool:
    return parity_summary(char_counts(normalize(s)))[0] <= 1


def build_palindrome(s: str) -> str:
    """Rearrange the characters of s into a palindrome, or return '' if impossible."""
    if not is_palindromic_permutation(s):
        return ""
    counts = char_counts(normalize(s))
    half: list[str] = []
    middle = ""
    for ch in sorted(counts):
        half.append(ch * (counts[ch] // 2))
        if counts[ch] % 2:
            middle = ch
    first = "".join(half)
    return first + middle + first[::-1]


def format_report(samples: list[str]) -> str:
    width = max(len(sample) for sample in samples)
    lines: list[str] = []
    for sample in samples:
        odd, even = parity_summary(char_counts(normalize(sample)))
        example = build_palindrome(sample) or "-"
        lines.append(f"{sample:<{width}}  odd={odd:<2} even={even:<2} {example}")
    return "\n".join(lines)


def main() -> None:
    samples: list[str] = ["Tact Coa", "aabbc", "hello world", "Never odd or even"]
    print(format_report(samples))
    totals: dict[str, int] = {"palindromic": 0, "not palindromic": 0}
    for sample in samples:
        key = "palindromic" if is_palindromic_permutation(sample) else "not palindromic"
        totals[key] += 1
    print(f"{totals['palindromic']} palindromic, {totals['not palindromic']} not")


if __name__ == "__main__":
    main()

