def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    if len(strings) == 1:
        return strings[0]

    min_len: int = min(len(s) for s in strings)

    prefix_chars: list[str] = []

    for i in range(min_len):
        char_to_check: str = strings[0][i]
        is_common: bool = True
        for s in strings:
            if s[i] != char_to_check:
                is_common = False
                break
        if is_common:
            prefix_chars.append(char_to_check)
        else:
            break

    result_prefix: str = "".join(prefix_chars)
    return result_prefix

