def to_pig_latin(word: str) -> str:
    """
    Converts a single word to Pig Latin.
    """
    vowels: set[str] = {'a', 'e', 'i', 'o', 'u'}

    if not word:
        return ""

    first_char: str = word[0]

    if first_char.lower() in vowels:
        return word + 'way'
    else:
        consonant_cluster_end_index: int = 0
        for i, char in enumerate(word):
            if char.lower() in vowels:
                consonant_cluster_end_index = i
                break
        else:
            return word + 'ay' # All consonants

        consonant_cluster: str = word[:consonant_cluster_end_index]
        remaining_word: str = word[consonant_cluster_end_index:]

        result: str = remaining_word + consonant_cluster + 'ay'
        return result

