def lcs_length(s1: str, s2: str) -> int:
    m: int = len(s1)
    n: int = len(s2)

    # dp[i][j] stores the length of LCS of s1[0...i-1] and s2[0...j-1]
    dp: list[list[int]] = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        row: list[int] = dp[i]
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                row[j] = dp[i - 1][j - 1] + 1
            else:
                row[j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

def main() -> None:
    test_cases: list[tuple[str, str, int]] = [
        ('ABCBDAB', 'BDCABA', 4),
        ('AGGTAB', 'GXTXAYB', 4),
        ('ABCD', 'ACDF', 3),
        ('AAAA', 'AA', 2)
    ]

    for s1, s2, expected in test_cases:
        result: int = lcs_length(s1, s2)
        print(f"LCS length of '{s1}' and '{s2}' is {result}. Expected: {expected}")
        assert result == expected, f"Test failed for '{s1}', '{s2}'. Expected {expected}, got {result}"

