FrequencyTable = dict[str, int]
CharCount = tuple[str, int]
Ranking = list[CharCount]


def count_char_frequencies(text: str) -> dict:
    """Count how often each character occurs in text (case-sensitive)."""
    frequencies: dict[str, int] = {}
    for char in text:
        frequencies[char] = frequencies.get(char, 0) + 1
    return frequencies


def rank_characters(frequencies: FrequencyTable) -> Ranking:
    """Order characters by descending count, then by character code."""
    return sorted(frequencies.items(), key=lambda item: (-item[1], item[0]))


def repeated_characters(frequencies: FrequencyTable) -> list[str]:
    """Characters that appear more than once, in ranked order."""
    return [char for char, count in rank_characters(frequencies) if count > 1]


def case_totals(frequencies: FrequencyTable) -> tuple[int, int]:
    """Total number of uppercase and lowercase letters."""
    upper = 0
    lower = 0
    for char, count in frequencies.items():
        if char.isupper():
            upper += count
        elif char.islower():
            lower += count
    return upper, lower


def merge_frequencies(tables: list[FrequencyTable]) -> FrequencyTable:
    """Combine several frequency tables into one."""
    merged: dict[str, int] = {}
    for table in tables:
        for char, count in table.items():
            merged[char] = merged.get(char, 0) + count
    return merged


def histogram_lines(frequencies: FrequencyTable) -> list[str]:
    """Render a ranked bar chart, one line per character."""
    lines: list[str] = []
    for char, count in rank_characters(frequencies):
        label = repr(char) if char.isspace() else char
        lines.append(f"{label:>4} | {'#' * count} ({count})")
    return lines


def describe(text: str) -> str:
    """Build a one-line summary of the character usage in text."""
    frequencies = count_char_frequencies(text)
    upper, lower = case_totals(frequencies)
    repeats = repeated_characters(frequencies)
    parts: list[str] = [f"{len(text)} chars", f"{len(frequencies)} distinct"]
    parts.append(f"{upper} upper / {lower} lower")
    if repeats:
        parts.append("repeated: " + ", ".join(repeats))
    return " | ".join(parts)


def main() -> None:
    samples = ["hello", "Python", "Mississippi River"]
    tables: list[FrequencyTable] = []
    for sample in samples:
        counts = count_char_frequencies(sample)
        tables.append(counts)
        print(f"{sample!r} -> {counts}")
        print("  " + describe(sample))

    combined = merge_frequencies(tables)
    top: Ranking = rank_characters(combined)[:5]
    print("\nTop five characters overall:")
    for char, count in top:
        print(f"  {char!r}: {count}")

    print("\nHistogram for 'Mississippi River':")
    for line in histogram_lines(tables[-1]):
        print(line)


if __name__ == "__main__":
    main()

