def parse_digits(card_number_str: str) -> list[int]:
    """Convert a string of digits into a list of integer digits."""
    stripped = card_number_str.replace(" ", "").replace("-", "")
    if not stripped:
        raise ValueError("card number must contain at least one digit")
    digits: list[int] = []
    for char in stripped:
        if not char.isdigit():
            raise ValueError(f"invalid character in card number: {char!r}")
        digits.append(int(char))
    return digits


def every_second_from_right(
    digits: list[int],
) -> list[int]:
    """Return the digits in positions 2, 4, 6 ... counting from the right."""
    return digits[::-1][1::2]


def remaining_digits(
    digits: list[int],
) -> list[int]:
    """Return the digits left over after taking every second one."""
    return digits[::-1][0::2]


def is_luhn_valid_simple(card_number_str: str) -> bool:
    digits = parse_digits(card_number_str)
    total = sum(every_second_from_right(digits)) + sum(remaining_digits(digits))
    return total % 10 == 0


def summarize(card_number_str: str) -> dict[str, int]:
    """Break a card number down into the parts used by the check."""
    digits = parse_digits(card_number_str)
    counts: dict[str, int] = {
        "length": len(digits),
        "second_sum": sum(every_second_from_right(digits)),
        "other_sum": sum(remaining_digits(digits)),
    }
    counts["total"] = counts["second_sum"] + counts["other_sum"]
    counts["remainder"] = counts["total"] % 10
    return counts


def check_digit_needed(card_number_str: str) -> int:
    """Digit that, appended, would make the number valid under this rule."""
    counts = summarize(card_number_str)
    return (10 - counts["remainder"]) % 10


def format_report(card_number_str: str) -> str:
    counts = summarize(card_number_str)
    verdict = "VALID" if is_luhn_valid_simple(card_number_str) else "INVALID"
    return (
        f"{card_number_str:<20} digits={counts['length']:>2} "
        f"total={counts['total']:>3} {verdict:<7} "
        f"append={check_digit_needed(card_number_str)}"
    )


def tally(
    card_numbers: list[str],
) -> dict[str, int]:
    results: dict[str, int] = {"valid": 0, "invalid": 0}
    for number in card_numbers:
        key = "valid" if is_luhn_valid_simple(number) else "invalid"
        results[key] += 1
    return results


def main() -> None:
    samples: list[str] = [
        "49927398716",
        "1234567890",
        "12345",
        "4111 1111 1111 1111",
    ]
    for number in samples:
        print(format_report(number))
    counts = tally(samples)
    print(f"\n{counts['valid']} valid, {counts['invalid']} invalid")


if __name__ == "__main__":
    main()

